import sys
input = sys.stdin.readline

def readList():
	return list(map(int, input().split()))

def readInt():
	return int(input())

def readInts():
	return map(int, input().split())

def readStr():
	return input().strip()

def solve():
	(n, m, k) = readInts()
	arr = readList()
	isPresent = [False] * (k + 1)
	curr = k
	cnt = 0
	for i in range(k):
		if arr[i] == curr:
			if cnt < n * m - 3:
				curr -= 1
				continue
			return 'TIDAK'
		else:
			while isPresent[curr] and curr > 0 and (cnt <= n * m - 3):
				isPresent[curr] = False
				cnt -= 1
				curr -= 1
			isPresent[arr[i]] = True
			cnt += 1
			if cnt > n * m - 2:
				return 'TIDAK'
	return 'YA'
for _ in range(int(input())):
	print(solve())
